-- Name: fn_proteger_cambio_familia_tipo_en_uso(); Type: FUNCTION; Schema: itam; Owner: itam_app
--

CREATE FUNCTION itam.fn_proteger_cambio_familia_tipo_en_uso() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.familia_codigo_inventario_id IS DISTINCT FROM
       OLD.familia_codigo_inventario_id
       AND EXISTS (
           SELECT 1
           FROM dispositivos
           WHERE tipo_dispositivo_id = OLD.id
       ) THEN
        RAISE EXCEPTION
            'No se puede mover este tipo a otra familia porque existen activos con códigos históricos asociados.'
            USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION itam.fn_proteger_cambio_familia_tipo_en_uso() OWNER TO itam_app;

--
-- Name: fn_proteger_cambio_tipo_dispositivo(); Type: FUNCTION; Schema: itam; Owner: itam_app
--

CREATE FUNCTION itam.fn_proteger_cambio_tipo_dispositivo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    familia_anterior BIGINT;
    familia_nueva BIGINT;
BEGIN
    IF NEW.tipo_dispositivo_id IS DISTINCT FROM OLD.tipo_dispositivo_id THEN
        SELECT familia_codigo_inventario_id
        INTO familia_anterior
        FROM tipos_dispositivo
        WHERE id = OLD.tipo_dispositivo_id;

        SELECT familia_codigo_inventario_id
        INTO familia_nueva
        FROM tipos_dispositivo
        WHERE id = NEW.tipo_dispositivo_id;

        IF familia_anterior IS DISTINCT FROM familia_nueva THEN
            RAISE EXCEPTION
                'No se puede cambiar el tipo porque contradice la familia histórica del código ITAM.'
                USING ERRCODE = 'P0001';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


