--
-- Name: fn_validar_estado_entidad(); Type: FUNCTION; Schema: itam; Owner: itam_app
--

CREATE FUNCTION itam.fn_validar_estado_entidad() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_tipo_entidad VARCHAR(20);
    v_activo       BOOLEAN;
BEGIN

    SELECT
        tipo_entidad,
        activo
    INTO
        v_tipo_entidad,
        v_activo
    FROM estados
    WHERE id = NEW.estado_id;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El estado con ID % no existe.',
            NEW.estado_id;
    END IF;


    IF v_tipo_entidad <> TG_ARGV[0] THEN
        RAISE EXCEPTION
            'Estado incompatible. Se esperaba un estado de tipo %, pero el estado seleccionado pertenece a %.',
            TG_ARGV[0],
            v_tipo_entidad;
    END IF;


    IF v_activo = FALSE THEN
        RAISE EXCEPTION
            'No se puede utilizar un estado que se encuentra inactivo.';
    END IF;


    RETURN NEW;

END;
$$;


ALTER FUNCTION itam.fn_validar_estado_entidad() OWNER TO itam_app;

--
-- Name: fn_validar_estado_historial(); Type: FUNCTION; Schema: itam; Owner: itam_app
--

CREATE FUNCTION itam.fn_validar_estado_historial() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_tipo VARCHAR(20);
BEGIN

    IF NEW.estado_anterior_id IS NOT NULL THEN

        SELECT tipo_entidad
        INTO v_tipo
        FROM estados
        WHERE id = NEW.estado_anterior_id;


        IF NOT FOUND OR v_tipo <> NEW.tipo_entidad THEN

            RAISE EXCEPTION
                'El estado anterior no corresponde al tipo de entidad %.',

                NEW.tipo_entidad;

        END IF;

    END IF;


    IF NEW.estado_nuevo_id IS NOT NULL THEN

        SELECT tipo_entidad
        INTO v_tipo
        FROM estados
        WHERE id = NEW.estado_nuevo_id;


        IF NOT FOUND OR v_tipo <> NEW.tipo_entidad THEN

            RAISE EXCEPTION
                'El estado nuevo no corresponde al tipo de entidad %.',

                NEW.tipo_entidad;

        END IF;

    END IF;


    RETURN NEW;

END;
$$;


ALTER FUNCTION itam.fn_validar_estado_historial() OWNER TO itam_app;

