    CONSTRAINT chk_custodia_tipo_cierre CHECK (((tipo_cierre IS NULL) OR ((tipo_cierre)::text = ANY ((ARRAY['DEVOLUCION'::character varying, 'REASIGNACION'::character varying, 'BAJA'::character varying, 'EXTRAVIO'::character varying, 'OFFBOARDING'::character varying, 'CONCILIACION_HISTORICA'::character varying, 'CORRECCION_ADMINISTRATIVA'::character varying])::text[])))),
    CONSTRAINT chk_custodia_tipo_inicio CHECK (((tipo_inicio)::text = ANY ((ARRAY['ASIGNACION'::character varying, 'ASIGNACION_DEPARTAMENTO'::character varying, 'IMPORTACION_HISTORICA'::character varying, 'RECONSTRUCCION_HISTORICA'::character varying, 'CORRECCION_ADMINISTRATIVA'::character varying])::text[]))),
    CONSTRAINT chk_custodia_un_custodio CHECK ((((colaborador_id IS NOT NULL) AND (departamento_id IS NULL)) OR ((colaborador_id IS NULL) AND (departamento_id IS NOT NULL)))),
    CONSTRAINT chk_custodia_vigencia CHECK ((((vigente = true) AND (tipo_cierre IS NULL) AND (fecha_fin IS NULL) AND (cerrado_en IS NULL)) OR ((vigente = false) AND (tipo_cierre IS NOT NULL) AND (cerrado_en IS NOT NULL))))
);


