    usuario_ejecutor_id bigint,
    CONSTRAINT chk_orden_custodio_ingreso CHECK ((((custodio_tipo_al_ingreso IS NULL) AND (colaborador_id_al_ingreso IS NULL) AND (departamento_id_al_ingreso IS NULL) AND (recibido_por_id_al_ingreso IS NULL)) OR (((custodio_tipo_al_ingreso)::text = 'COLABORADOR'::text) AND (colaborador_id_al_ingreso IS NOT NULL) AND (departamento_id_al_ingreso IS NULL) AND (recibido_por_id_al_ingreso IS NULL)) OR (((custodio_tipo_al_ingreso)::text = 'DEPARTAMENTO'::text) AND (colaborador_id_al_ingreso IS NULL) AND (departamento_id_al_ingreso IS NOT NULL) AND (recibido_por_id_al_ingreso IS NOT NULL)))),
    CONSTRAINT chk_orden_servicio_decision CHECK (((decision IS NULL) OR ((decision)::text = ANY ((ARRAY['APROBAR'::character varying, 'RECHAZAR'::character varying, 'DAR_BAJA'::character varying])::text[])))),
    CONSTRAINT chk_orden_servicio_estado CHECK (((estado)::text = ANY ((ARRAY['PENDIENTE_DIAGNOSTICO'::character varying, 'COTIZACION_RECIBIDA'::character varying, 'REPARACION_APROBADA'::character varying, 'REPARACION_RECHAZADA'::character varying, 'EN_REPARACION'::character varying, 'REPARACION_TERMINADA'::character varying, 'CERRADA'::character varying, 'BAJA'::character varying])::text[]))),
    CONSTRAINT chk_orden_servicio_montos CHECK ((((monto_cotizacion IS NULL) OR (monto_cotizacion >= 0)) AND ((costo_final IS NULL) OR (costo_final >= 0))))
);


