--
-- Name: usuarios; Type: TABLE; Schema: itam; Owner: itam_app
--

CREATE TABLE itam.usuarios (
    id bigint NOT NULL,
    nombre character varying(180) NOT NULL,
    email character varying(254) NOT NULL,
    password_hash text NOT NULL,
    rol character varying(30) NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    creado_en timestamp with time zone DEFAULT now() NOT NULL,
    actualizado_en timestamp with time zone DEFAULT now() NOT NULL,
    cargo character varying(150),
    debe_cambiar_password boolean DEFAULT false NOT NULL,
    pin_hash text,
    pin_intentos_fallidos smallint DEFAULT 0 NOT NULL,
    pin_bloqueado_hasta timestamp with time zone,
    debe_cambiar_pin boolean DEFAULT false NOT NULL,
    CONSTRAINT chk_usuario_pin_configuracion CHECK (((pin_hash IS NOT NULL) OR ((pin_intentos_fallidos = 0) AND (pin_bloqueado_hasta IS NULL) AND (debe_cambiar_pin = false)))),
    CONSTRAINT chk_usuario_pin_hash CHECK (((pin_hash IS NULL) OR (pin_hash ~~ 'scrypt$%'::text))),
    CONSTRAINT chk_usuario_pin_intentos CHECK (((pin_intentos_fallidos >= 0) AND (pin_intentos_fallidos <= 5))),
    CONSTRAINT chk_usuario_rol CHECK (((rol)::text = ANY ((ARRAY['SUPER_USUARIO'::character varying, 'USUARIO'::character varying])::text[])))
);


